-- Extends the same disposable canonical draft proof transaction.
RESET ROLE;
\ir ../../supabase/migrations/20270584000000_sales_draft_catalog_facts.sql
\ir ../../supabase/migrations/20270584000000_sales_draft_catalog_facts.sql
UPDATE tenant_prices SET active=true,unit_amount=350000 WHERE id='50000000-0000-0000-0000-000000000001';
CREATE TEMP TABLE catalog_draft_command AS SELECT jsonb_set(command,'{invoice_id}','"60000000-0000-0000-0000-000000000840"') || jsonb_build_object('draft',(command->'draft')||jsonb_build_object('items',jsonb_build_array(jsonb_build_object('price_id','50000000-0000-0000-0000-000000000001','item','Test service','unit_minor',NULL,'quantity',1)))) command FROM governed_draft_command;
UPDATE catalog_draft_command SET command=command||jsonb_build_object('catalog_prices',read_sales_invoice_draft_catalog('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001',command->'draft')->'prices');
GRANT SELECT ON catalog_draft_command TO service_role;
SELECT proof_assert(NOT has_function_privilege('authenticated','read_sales_invoice_draft_catalog(uuid,uuid,jsonb,boolean)','EXECUTE') AND NOT has_function_privilege('anon','read_sales_invoice_draft_intent_result(uuid,uuid,uuid,jsonb)','EXECUTE'),'catalog helpers cannot accept browser-supplied actors');
UPDATE tenant_prices SET unit_amount=350001 WHERE id='50000000-0000-0000-0000-000000000001';
SET ROLE service_role;
SELECT proof_denied($q$SELECT execute_sales_invoice_draft_command('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000840',(SELECT command FROM catalog_draft_command),proof_draft_governance('invoice.draft_create','billing_create_invoice'))$q$,'40001','changed reviewed price refuses before invoice mutation');
RESET ROLE;
SELECT proof_assert(NOT EXISTS(SELECT 1 FROM paige_invoices WHERE id='60000000-0000-0000-0000-000000000840'),'stale price leaves no invoice');
UPDATE tenant_prices SET active=true,unit_amount=350000 WHERE id='50000000-0000-0000-0000-000000000001';
SET ROLE service_role;
CREATE TEMP TABLE catalog_draft_result AS SELECT execute_sales_invoice_draft_command('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000840',command,proof_draft_governance('invoice.draft_create','billing_create_invoice')) result FROM catalog_draft_command;
SELECT proof_assert((SELECT result#>>'{row,billing_draft,due_now_minor}'='50000' AND result#>>'{row,billing_draft,remainder_minor}'='300000' FROM catalog_draft_result),'catalog draft uses canonical writer exact deposit and balance');
RESET ROLE;
UPDATE tenant_prices SET active=false,unit_amount=1 WHERE id='50000000-0000-0000-0000-000000000001';
SET ROLE service_role;
SELECT proof_assert((SELECT read_sales_invoice_draft_intent_result('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000840',command-'catalog_prices')=result FROM catalog_draft_command CROSS JOIN catalog_draft_result),'immutable intent replay survives later price deactivation without mutation');
SELECT proof_denied($q$SELECT read_sales_invoice_draft_intent_result('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000840',(SELECT jsonb_set(command-'catalog_prices','{draft,memo}','"Different intent"') FROM catalog_draft_command))$q$,'22023','reused operation changed intent refuses');
SELECT proof_denied($q$SELECT read_sales_invoice_draft_catalog('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001',(SELECT command->'draft' FROM catalog_draft_command))$q$,'22023','inactive price cannot create new draft');
RESET ROLE;
SELECT proof_assert((SELECT count(*)=1 FROM paige_invoice_operations WHERE id='70000000-0000-0000-0000-000000000840') AND (SELECT count(*)=1 FROM paige_workspace_events WHERE source_id='70000000-0000-0000-0000-000000000840'),'catalog replay has one operation and one canonical Rail event');
RESET ROLE;
UPDATE tenant_prices SET active=true,unit_amount=350000,currency='eur' WHERE id='50000000-0000-0000-0000-000000000001';
SET ROLE service_role;
SELECT proof_denied($q$SELECT read_sales_invoice_draft_catalog('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001',(SELECT command->'draft' FROM catalog_draft_command))$q$,'22023','unsupported currency never becomes USD by inference');
RESET ROLE;
UPDATE tenant_prices SET currency='usd',kind='installment',installments_total=10 WHERE id='50000000-0000-0000-0000-000000000001';
SET ROLE service_role;
SELECT proof_denied($q$SELECT read_sales_invoice_draft_catalog('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001',(SELECT command->'draft' FROM catalog_draft_command))$q$,'22023','installment cycle price cannot be coerced into total obligation');
RESET ROLE;
UPDATE tenant_prices SET kind='one_time',installments_total=NULL WHERE id='50000000-0000-0000-0000-000000000001';
UPDATE tenant_products SET name='Changed offer' WHERE id='40000000-0000-0000-0000-000000000001';
SET ROLE service_role;
SELECT proof_denied($q$SELECT execute_sales_invoice_draft_command('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000842',(SELECT jsonb_set(command,'{invoice_id}','"60000000-0000-0000-0000-000000000842"') FROM catalog_draft_command),proof_draft_governance('invoice.draft_create','billing_create_invoice'))$q$,'40001','changed offer name requires fresh review');
RESET ROLE;
UPDATE tenant_products SET name='Test service' WHERE id='40000000-0000-0000-0000-000000000001';
UPDATE tenant_prices SET active=true,unit_amount=999 WHERE id='50000000-0000-0000-0000-000000000001';
CREATE FUNCTION proof_catalog_rail_fail() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.source_id='70000000-0000-0000-0000-000000000843' THEN RAISE EXCEPTION 'Injected catalog receipt failure' USING ERRCODE='55000'; END IF; RETURN NEW; END $$;
CREATE TRIGGER proof_catalog_rail_fail BEFORE INSERT ON paige_workspace_events FOR EACH ROW EXECUTE FUNCTION proof_catalog_rail_fail();
UPDATE tenant_prices SET unit_amount=350000 WHERE id='50000000-0000-0000-0000-000000000001';
SET ROLE service_role;
SELECT proof_denied($q$SELECT execute_sales_invoice_draft_command('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000843',(SELECT jsonb_set(command,'{invoice_id}','"60000000-0000-0000-0000-000000000843"') FROM catalog_draft_command),proof_draft_governance('invoice.draft_create','billing_create_invoice'))$q$,'55000','catalog receipt failure rolls whole canonical draft back');
RESET ROLE;
SELECT proof_assert(NOT EXISTS(SELECT 1 FROM paige_invoices WHERE id='60000000-0000-0000-0000-000000000843') AND NOT EXISTS(SELECT 1 FROM paige_invoice_operations WHERE id='70000000-0000-0000-0000-000000000843'),'failed catalog receipt leaves no invoice or operation');
DROP TRIGGER proof_catalog_rail_fail ON paige_workspace_events;
CREATE TABLE proof_catalog_lock AS SELECT jsonb_set(command,'{invoice_id}','"60000000-0000-0000-0000-000000000841"') command FROM catalog_draft_command;
GRANT SELECT ON proof_catalog_lock TO service_role;
